// catalog.js — 读者馆藏浏览：检索、分类筛选、自助借阅。
import { api } from "../api.js";
import { esc, loading, renderTable, toast } from "../components.js";

export async function renderCatalog(container) {
  loading(container);
  const categories = await api.listCategories();
  const wrap = document.createElement("div");
  wrap.innerHTML = `
    <div class="toolbar">
      <input class="input" id="kw" placeholder="搜索书名 / 作者 / ISBN" />
      <select class="input" id="cat" style="min-width:140px">
        <option value="">全部分类</option>
        ${categories.map((c) => `<option value="${c.id}">${esc(c.name)}</option>`).join("")}
      </select>
      <button class="btn btn-primary btn-sm" id="search">查询</button>
    </div>
    <div id="table"></div>`;
  container.innerHTML = "";
  container.appendChild(wrap);
  const tableEl = wrap.querySelector("#table");

  const load = async () => {
    loading(tableEl);
    const books = await api.listBooks({
      keyword: wrap.querySelector("#kw").value.trim(),
      category: wrap.querySelector("#cat").value,
    });
    tableEl.innerHTML = "";
    renderTable(
      tableEl,
      [
        { key: "title", title: "书名", render: (r) =>
          `<div>${esc(r.title)}</div><div class="muted" style="font-size:12px">${esc(r.author)} · ${esc(r.publisher)}</div>` },
        { key: "category", title: "分类" },
        { key: "location", title: "馆藏位置" },
        {
          key: "availableQty", title: "可借/总册", align: "center",
          render: (r) => `${r.availableQty} / ${r.totalQty}`,
        },
        {
          title: "操作", align: "right",
          render: (r) => `<div class="row-actions">
            <button class="btn ${r.availableQty > 0 ? "btn-primary" : "btn-ghost"} btn-sm act-borrow"
              ${r.availableQty > 0 ? "" : "disabled"}>
              ${r.availableQty > 0 ? "借阅" : "已借完"}</button></div>`,
        },
      ],
      books
    );

    tableEl.querySelectorAll(".act-borrow").forEach((b) =>
      b.addEventListener("click", async () => {
        const book = books[Number(b.closest("tr").rowIndex) - 1];
        b.disabled = true;
        try {
          await api.selfBorrow(book.id);
          toast(`《${book.title}》借阅成功`, "success");
          load();
        } catch (err) { toast(err.message, "error"); b.disabled = false; }
      })
    );
  };

  wrap.querySelector("#search").onclick = load;
  wrap.querySelector("#kw").addEventListener("keydown", (e) => { if (e.key === "Enter") load(); });
  load();
}

// dashboard.js — 管理员控制台：核心指标、分类馆藏、热门图书。
import { api } from "../api.js";
import { esc, loading, renderTable } from "../components.js";

function statCard(label, value, ico, icoClass) {
  return `<div class="stat-card">
    <div class="stat-ico ${icoClass}">${ico}</div>
    <div class="stat-label">${esc(label)}</div>
    <div class="stat-value">${value}</div>
  </div>`;
}

export async function renderDashboard(container) {
  loading(container);
  const [dash, catStats, hot] = await Promise.all([
    api.dashboard(),
    api.categoryStats(),
    api.hotBooks(),
  ]);

  container.innerHTML = `
    <div class="stat-grid">
      ${statCard("图书种类", dash.bookKinds, "📚", "ico-blue")}
      ${statCard("图书总册数", dash.bookCopies, "📖", "ico-green")}
      ${statCard("注册读者", dash.readers, "👤", "ico-orange")}
      ${statCard("当前借出", dash.borrowed, "🔖", "ico-blue")}
      ${statCard("逾期未还", dash.overdue, "⚠", "ico-red")}
    </div>
    <div class="grid-2">
      <div class="card">
        <h3 class="card-title">分类馆藏分布</h3>
        <div id="cat-bars"></div>
      </div>
      <div class="card">
        <h3 class="card-title">热门图书（按借阅次数）</h3>
        <div id="hot-table"></div>
      </div>
    </div>`;

  // 分类条形图
  const maxCopies = Math.max(1, ...catStats.map((c) => c.copies));
  const bars = container.querySelector("#cat-bars");
  if (!catStats.length) {
    bars.innerHTML = `<p class="muted">暂无数据</p>`;
  } else {
    bars.innerHTML = catStats
      .map(
        (c) => `
      <div class="bar-row">
        <div class="bar-label" title="${esc(c.name)}">${esc(c.name)}</div>
        <div class="bar-track"><div class="bar-fill" style="width:${(c.copies / maxCopies) * 100}%"></div></div>
        <div class="bar-value">${c.copies} 册</div>
      </div>`
      )
      .join("");
  }

  renderTable(
    container.querySelector("#hot-table"),
    [
      { key: "title", title: "书名" },
      { key: "author", title: "作者" },
      { key: "times", title: "借阅次数", align: "right" },
    ],
    hot
  );
}

// logs.js — 管理员操作日志查看。
import { api } from "../api.js";
import { loading, renderTable } from "../components.js";

export async function renderLogs(container) {
  loading(container);
  const logs = await api.logs();
  container.innerHTML = `<div class="card"><h3 class="card-title">最近操作日志</h3><div id="table"></div></div>`;
  renderTable(
    container.querySelector("#table"),
    [
      { key: "createdAt", title: "时间" },
      { key: "username", title: "操作用户" },
      { key: "action", title: "操作类型" },
      { key: "detail", title: "详情" },
    ],
    logs
  );
}

// myborrows.js — 读者我的借阅：在借（可续借一次）/ 历史记录。
import { api } from "../api.js";
import { loading, renderTable, toast, badge } from "../components.js";

function stateBadge(r) {
  if (r.status === "returned") return badge("已归还", "gray");
  if (r.state && r.state.includes("逾期")) return badge(r.state, "red");
  return badge(r.state || "正常", "green");
}

export async function renderMyBorrows(container) {
  loading(container);
  const wrap = document.createElement("div");
  wrap.innerHTML = `
    <div class="login-tabs" style="max-width:340px">
      <button data-t="active" class="active">当前借阅</button>
      <button data-t="history">历史记录</button>
    </div>
    <div id="table" style="margin-top:16px"></div>`;
  container.innerHTML = "";
  container.appendChild(wrap);
  const tableEl = wrap.querySelector("#table");
  let mode = "active";

  const columnsActive = [
    { key: "title", title: "书名" },
    { key: "borrowDate", title: "借出日期" },
    { key: "dueDate", title: "应还日期" },
    { key: "renewCount", title: "已续借", align: "center", render: (r) => `${r.renewCount} 次` },
    { title: "状态", align: "center", render: stateBadge },
    {
      title: "操作", align: "right",
      render: (r) => `<div class="row-actions">
        <button class="btn ${r.renewCount === 0 ? "btn-outline" : "btn-ghost"} btn-sm act-renew"
          ${r.renewCount === 0 ? "" : "disabled"}>
          ${r.renewCount === 0 ? "续借" : "不可续借"}</button></div>`,
    },
  ];
  const columnsHistory = [
    { key: "title", title: "书名" },
    { key: "borrowDate", title: "借出日期" },
    { key: "returnDate", title: "归还日期" },
    { key: "renewCount", title: "续借次数", align: "center" },
    {
      key: "fine", title: "罚款(元)", align: "right",
      render: (r) => (r.fine > 0 ? `<span style="color:var(--danger)">${r.fine.toFixed(2)}</span>` : "0.00"),
    },
    { title: "状态", align: "center", render: stateBadge },
  ];

  const load = async () => {
    loading(tableEl);
    const recs = mode === "active" ? await api.myActive() : await api.myHistory();
    tableEl.innerHTML = "";
    renderTable(tableEl, mode === "active" ? columnsActive : columnsHistory, recs);
    tableEl.querySelectorAll(".act-renew").forEach((b) =>
      b.addEventListener("click", async () => {
        const r = recs[Number(b.closest("tr").rowIndex) - 1];
        try {
          await api.selfRenew(r.id);
          toast("续借成功，应还日期已延长 30 天", "success");
          load();
        } catch (err) { toast(err.message, "error"); }
      })
    );
  };

  wrap.querySelectorAll(".login-tabs button").forEach((b) =>
    b.addEventListener("click", () => {
      wrap.querySelectorAll(".login-tabs button").forEach((x) => x.classList.remove("active"));
      b.classList.add("active");
      mode = b.dataset.t;
      load();
    })
  );

  load();
}

// profile.js — 读者个人信息。
import { api } from "../api.js";
import { esc, loading } from "../components.js";

export async function renderProfile(container) {
  loading(container);
  const [me, reader] = await Promise.all([api.me(), api.myReader()]);
  container.innerHTML = `
    <div class="card" style="max-width:560px">
      <h3 class="card-title">个人信息</h3>
      <dl class="desc-list">
        <dt>读者编号</dt><dd>${esc(reader.readerNo)}</dd>
        <dt>姓名</dt><dd>${esc(reader.name)}</dd>
        <dt>手机号</dt><dd>${esc(reader.phone)}</dd>
        <dt>登录用户名</dt><dd>${esc(me.username)}</dd>
        <dt>注册时间</dt><dd>${esc(reader.createdAt)}</dd>
      </dl>
      <p class="form-hint" style="margin-top:18px">如需修改登录口令，请点击右上角“修改口令”。</p>
    </div>`;
}

// readers.js — 管理员读者管理：检索、新增、启用/停用、重置口令。
import { api } from "../api.js";
import {
  esc, loading, renderTable, openModal, confirmDialog, toast, formValues, badge,
} from "../components.js";

function readerForm() {
  const form = document.createElement("form");
  form.innerHTML = `
    <div class="form-row">
      <div class="field"><label>真实姓名</label><input class="input" name="realName" required /></div>
      <div class="field"><label>手机号</label><input class="input" name="phone" /></div>
    </div>
    <div class="form-row">
      <div class="field"><label>登录用户名</label><input class="input" name="username" required /></div>
      <div class="field"><label>初始口令</label><input class="input" name="password" value="reader123" required /></div>
    </div>
    <p class="form-hint">默认初始口令 reader123，读者登录后可自行修改。</p>`;
  return form;
}

export async function renderReaders(container) {
  loading(container);
  const wrap = document.createElement("div");
  wrap.innerHTML = `
    <div class="toolbar">
      <input class="input" id="kw" placeholder="搜索姓名 / 读者编号 / 用户名" />
      <button class="btn btn-primary btn-sm" id="search">查询</button>
      <div class="spacer"></div>
      <button class="btn btn-primary btn-sm" id="add-reader">+ 新增读者</button>
    </div>
    <div id="table"></div>`;
  container.innerHTML = "";
  container.appendChild(wrap);
  const tableEl = wrap.querySelector("#table");

  const load = async () => {
    loading(tableEl);
    const keyword = wrap.querySelector("#kw").value.trim();
    const readers = await api.listReaders(keyword);
    tableEl.innerHTML = "";
    renderTable(
      tableEl,
      [
        { key: "readerNo", title: "读者编号" },
        { key: "name", title: "姓名" },
        { key: "phone", title: "手机号" },
        { key: "username", title: "登录用户名" },
        {
          key: "status", title: "状态", align: "center",
          render: (r) => badge(r.status === "active" ? "正常" : "已停用", r.status === "active" ? "green" : "gray"),
        },
        { key: "createdAt", title: "注册时间" },
        {
          title: "操作", align: "right",
          render: (r) => `
            <div class="row-actions">
              <button class="btn btn-ghost btn-sm act-pwd">重置口令</button>
              <button class="btn ${r.status === "active" ? "btn-danger" : "btn-outline"} btn-sm act-toggle">
                ${r.status === "active" ? "停用" : "启用"}</button>
            </div>`,
        },
      ],
      readers
    );

    tableEl.querySelectorAll(".act-pwd").forEach((b) =>
      b.addEventListener("click", async () => {
        const r = readers[Number(b.closest("tr").rowIndex) - 1];
        if (await confirmDialog(`确定将 ${r.name} 的口令重置为临时口令吗？`, { okText: "重置" })) {
          try {
            const res = await api.resetReaderPassword(r.userId);
            openModal({
              title: "口令已重置",
              body: `<p>读者 <b>${esc(r.name)}</b> 的新临时口令为：</p>
                <p style="font-size:20px;font-weight:700;letter-spacing:1px">${esc(res.tempPassword)}</p>
                <p class="form-hint">请告知读者尽快登录修改。</p>`,
              footer: "",
            });
          } catch (err) { toast(err.message, "error"); }
        }
      })
    );

    tableEl.querySelectorAll(".act-toggle").forEach((b) =>
      b.addEventListener("click", async () => {
        const r = readers[Number(b.closest("tr").rowIndex) - 1];
        const toActive = r.status !== "active";
        if (await confirmDialog(`确定${toActive ? "启用" : "停用"}读者 ${r.name} 吗？`, { okText: "确定" })) {
          try {
            await api.setReaderStatus(r.userId, toActive ? "active" : "disabled");
            toast("状态已更新", "success");
            load();
          } catch (err) { toast(err.message, "error"); }
        }
      })
    );
  };

  wrap.querySelector("#search").onclick = load;
  wrap.querySelector("#kw").addEventListener("keydown", (e) => { if (e.key === "Enter") load(); });
  wrap.querySelector("#add-reader").onclick = () => {
    const form = readerForm();
    const footer = document.createElement("div");
    const btnCancel = document.createElement("button");
    btnCancel.className = "btn btn-ghost"; btnCancel.textContent = "取消";
    const btnSave = document.createElement("button");
    btnSave.className = "btn btn-primary"; btnSave.textContent = "保存";
    footer.append(btnCancel, btnSave);
    const m = openModal({ title: "新增读者", body: form, footer });
    btnCancel.onclick = m.close;
    btnSave.onclick = async () => {
      const v = formValues(form);
      btnSave.disabled = true;
      try {
        const res = await api.createReader(v);
        toast(`读者已新增，编号 ${res.readerNo}`, "success");
        m.close();
        load();
      } catch (err) { toast(err.message, "error"); btnSave.disabled = false; }
    };
  };

  load();
}

